var t=[{title:`Estimez votre hauteur d’atteinte`,text:`Tenez-vous debout sur la surface où vous vous entraînerez et levez naturellement les bras au-dessus de la tête. Ajoutez ensuite la hauteur de l’haltère, du kettlebell, de la barre ou de tout autre engin au-dessus de vos mains. Laissez de la place pour un mouvement contrôlé afin que l’objet ne s’arrête jamais juste sous le plafond.`},{title:`Le mouvement demande plus que la taille debout`,text:`Les sauts ajoutent de la course verticale, et une corde à sauter passe au-dessus de votre tête. Les tractions demandent de la place au-dessus de la barre pour votre tête et en dessous pour vos pieds, et les barres de porte demandent aussi un dégagement sûr à l’endroit de leur fixation. Les ventilateurs de plafond, les lampes, les tuyaux et les poutres apparentes peuvent réduire la hauteur réellement utilisable.`},{title:`Testez le mouvement à vide`,text:`Si le plafond semble assez haut, répétez le mouvement sans charge et vérifiez le point le plus haut depuis une position sûre. Ne testez jamais en soulevant quelque chose de lourd vers un plafond bas. Même une personne de petite taille peut avoir besoin de plus de place que prévu, car l’engin se déplace au-dessus des mains.`},{title:`Substitutions pratiques`,text:`Sous un plafond bas, des développés au sol peuvent remplacer les développés au-dessus de la tête, et des rowings peuvent remplacer les tractions si l’installation ou le dégagement de la barre ne convient pas. Pour le cardio, choisissez la marche sur place, les montées sur marche ou la boxe dans le vide plutôt que la corde à sauter ou les jumping jacks avec les bras au-dessus de la tête. Ces échanges ne travaillent pas forcément exactement la même action articulaire, mais ils respectent l’objectif de la séance.`},{title:`Avec TrainUp`,text:`Saisissez la hauteur de votre plafond dans Profil, avec la taille de votre espace au sol. Le programme exclut les exercices au-dessus de la tête et les sauts qui demandent plus de dégagement que vous n’en avez.`}];var a=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic : sécurité et technique en musculation`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var l={sections:t,sources:a};export{l as default,t as sections,a as sources};